from playwright.sync_api import sync_playwright,expect
today=datetime.date.today().isoformat()
data={'version':1,'budgets':[],'bills':[{'id':f'bill-{i}','name':f'Conta {i:02d}','date':today,'cents':1000+i,'paid':False} for i in range(25)],'goals':[{'id':f'goal-{i}','name':f'Meta {i:02d}','target':100000,'saved':i*100} for i in range(50)]}
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);ctx=b.new_context(viewport={'width':390,'height':844},service_workers='block');ctx.route('**/config.js',lambda r:r.fulfill(content_type='application/javascript',body="export const cloudConfig={url:'',publishableKey:''};"));ctx.add_init_script('localStorage.setItem("serimora.planning.v1.local",'+json.dumps(json.dumps(data))+');');page=ctx.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(os.environ.get('SALDO_TEST_URL','http://127.0.0.1:8110'));page.locator('#local-mode').click();page.locator('#alerts-open').click();page.locator('.notification-card').filter(has_text='Conta 24').locator('h3').click();expect(page.locator('#planning')).to_be_visible();expect(page.locator('#bill-list .planning-item')).to_have_count(1);target=page.locator('#bill-list [data-planning-key="bill-24"]');expect(target).to_be_focused();expect(target).to_have_class('planning-item planning-highlight');assert target.evaluate('(e)=>e.getAnimations().some(a=>a.effect.getKeyframes().some(f=>f.transform?.includes("translateX")))');expect(page.locator('#bill-form')).to_be_hidden();expect(page.locator('[data-planning-panel=goal]')).to_be_hidden()
 page.locator('#bill-show-all').click();expect(page.locator('#bill-list .planning-item')).to_have_count(10);page.locator('#bill-pagination').get_by_role('button',name='Próxima').click();expect(page.locator('#bill-pagination')).to_contain_text('Página 2 de 3');page.locator('#bill-search').fill('Conta 24');expect(page.locator('#bill-list .planning-item')).to_have_count(1);expect(page.locator('#bill-list')).to_contain_text('Conta 24')
 page.locator('.planning-tabs [data-planning-view=goal]').click();expect(page.locator('#goal-list .planning-item')).to_have_count(10);expect(page.locator('#goal-pagination')).to_contain_text('Página 1 de 5');page.locator('#goal-pagination').get_by_role('button',name='Próxima').click();expect(page.locator('#goal-pagination')).to_contain_text('Página 2 de 5');page.locator('#goal-search').fill('Meta 49');expect(page.locator('#goal-list .planning-item')).to_have_count(1)
 page.locator('.planning-tabs [data-planning-view=overview]').click();expect(page.locator('#planning-overview')).to_be_visible();expect(page.locator('[data-planning-panel=goal]')).to_be_hidden()
 page.emulate_media(reduced_motion='reduce');page.locator('#alerts-open').click();page.locator('.notification-card').filter(has_text='Conta 24').get_by_role('button',name='Ver conta').click();target=page.locator('#bill-list [data-planning-key="bill-24"]');expect(target).to_be_focused();assert target.evaluate('(e)=>e.getAnimations().length')==0
